  ('holy_livramento_na_fornalha', 'Livramento na Fornalha', 'background', 'background', 'holy', 'O livramento narrado no episódio da fornalha. Representação simbólica, inspirada em Daniel 3:24-27. Representação simbólica para o Santuário; o objeto não é divino e não confere poder.', 'Daniel 3:24-27', 'background/holy_livramento_na_fornalha', false, false, 7, null, null, 'milestone', 'oficial-v2', null, 'symbolic', 'O livramento narrado no episódio da fornalha', 'Pai', 'obra', false, null, true),
