  ('holy_paes_da_multiplicacao', 'Pães da Multiplicação', 'relic', 'relic', 'holy', 'A multiplicação dos pães. Representação simbólica, inspirada em João 6:11-13. Representação simbólica para o Santuário; o objeto não é divino e não confere poder.', 'João 6:11-13', 'relic/holy_paes_da_multiplicacao', false, false, 7, null, null, 'milestone', 'oficial-v2', null, 'symbolic', 'A multiplicação dos pães', 'Filho', 'obra', false, null, true),
  ('holy_tumulo_vazio', 'Túmulo Vazio', 'background', 'background', 'holy', 'Símbolo da ressurreição de Jesus. Representação simbólica, inspirada em Lucas 24:2-6. Representação simbólica para o Santuário; o objeto não é divino e não confere poder.', 'Lucas 24:2-6', 'background/holy_tumulo_vazio', false, false, 7, null, null, 'milestone', 'oficial-v2', null, 'symbolic', 'Símbolo da ressurreição de Jesus', 'Filho', 'obra', false, null, true),
  ('holy_cenario_do_monte_da_transfiguracao', 'Cenário do Monte da Transfiguração', 'background', 'background', 'holy', 'Representação do cenário da transfiguração sem personificar Deus como item. Representação simbólica, inspirada em Mateus 17:1-5. Representação simbólica para o Santuário; o objeto não é divino e não confere poder.', 'Mateus 17:1-5', 'background/holy_cenario_do_monte_da_transfiguracao', false, false, 7, null, null, 'milestone', 'oficial-v2', null, 'symbolic', 'Representação do cenário da transfiguração sem personificar Deus como item', 'Filho', 'obra', false, null, true),
  ('holy_sinal_da_pomba', 'Sinal da Pomba', 'frame', 'frame', 'holy', 'Símbolo da descida do Espírito no batismo de Jesus. Representação simbólica, inspirada em Mateus 3:16. Representação simbólica para o Santuário; o objeto não é divino e não confere poder.', 'Mateus 3:16', 'frame/holy_sinal_da_pomba', false, false, 7, null, null, 'milestone', 'oficial-v2', null, 'symbolic', 'Símbolo da descida do Espírito no batismo de Jesus', 'Espírito Santo', 'simbolo', false, null, true),
  ('holy_chamas_de_pentecostes', 'Chamas de Pentecostes', 'effect', 'effect', 'holy', 'Sinal visual das línguas como de fogo. Representação simbólica, inspirada em Atos 2:1-4. Representação simbólica para o Santuário; o objeto não é divino e não confere poder.', 'Atos 2:1-4', 'effect/holy_chamas_de_pentecostes', false, false, 7, null, null, 'milestone', 'oficial-v2', null, 'symbolic', 'Sinal visual das línguas como de fogo', 'Espírito Santo', 'obra', false, null, true),
  ('holy_selo_da_promessa', 'Selo da Promessa', 'frame', 'frame', 'holy', 'Representação simbólica do Espírito como selo. Representação simbólica, inspirada em Efésios 1:13. Representação simbólica para o Santuário; o objeto não é divino e não confere poder.', 'Efésios 1:13', 'frame/holy_selo_da_promessa', false, false, 7, null, null, 'milestone', 'oficial-v2', null, 'symbolic', 'Representação simbólica do Espírito como selo', 'Espírito Santo', 'simbolo', false, null, true),
  ('holy_cenario_da_nova_criacao', 'Cenário da Nova Criação', 'background', 'background', 'holy', 'Representação artística da promessa de todas as coisas novas. Representação simbólica, inspirada em Apocalipse 21:1-5. Representação simbólica para o Santuário; o objeto não é divino e não confere poder.', 'Apocalipse 21:1-5', 'background/holy_cenario_da_nova_criacao', false, false, 7, null, null, 'milestone', 'oficial-v2', null, 'symbolic', 'Representação artística da promessa de todas as coisas novas', 'Deus Triúno', 'obra', false, null, true),
  ('sandals-desert', 'Sandálias do Deserto', 'footwear', 'feet', 'rare', 'Inspiradas no chamado de Moisés diante da sarça, quando ouviu: “tira as sandálias dos pés” (Êxodo 3:5). Simbólicas, sem pretensão de autenticidade histórica.', 'Êxodo 3:5', 'feet/sandals-desert', false, false, 7, null, null, 'reading', 'complementar', null, 'inspired', null, null, null, false, null, true),
  ('staff-moses', 'Vara de Moisés', 'tool', 'hands', 'rare', 'Lembra a vara que Moisés estendeu sobre o mar (Êxodo 14:16). Item simbólico, sem poderes.', 'Êxodo 14:16', 'hands/staff-moses', false, false, 7, null, null, 'reading', 'complementar', null, 'inspired', null, null, null, false, null, true),
  ('cloak-succession', 'Manto da Sucessão', 'cloak', 'back', 'rare', 'Evolução visual do Manto de Elias, lembrando quando Eliseu apanhou o manto e seguiu o chamado (2 Reis 2:13-14). A versão original continua no inventário.', '2 Reis 2:13-14', 'back/cloak-succession', false, false, 7, null, 'Após a passagem a Eliseu', 'reading', 'complementar', null, 'inspired', null, null, null, false, null, true),
  ('cloak-elijah-prophets', 'Manto de Elias — Edição dos Profetas', 'cloak', 'back', 'epic', 'Aparência especial do Manto de Elias, recompensa da Coleção dos Profetas. Puramente cosmética.', '1 Reis 19:19; 2 Reis 2:13-14', 'back/cloak-elijah-prophets', false, false, 7, null, 'Edição especial de coleção', 'collection', 'complementar', null, 'inspired', null, null, null, false, null, true),
  ('scroll-isaiah', 'Rolo de Isaías', 'scroll', 'hands', 'rare', 'Lendário de Isaías: lembra o chamado do profeta (Isaías 6:8) e o rolo lido em Nazaré (Lucas 4:17).', 'Isaías 6:8; Lucas 4:17', 'hands/scroll-isaiah', false, false, 7, null, null, 'reading', 'complementar', null, 'inspired', null, null, null, false, null, true),
  ('frame-complete', 'Moldura Jornada Completa', 'frame', 'frame', 'epic', 'Celebra a leitura dos 1.189 capítulos da Bíblia (66 livros). “Lâmpada para os meus pés é a tua palavra” (Salmos 119:105).', 'Salmos 119:105', 'frame/frame-complete', false, false, 7, null, null, 'milestone', 'complementar', null, 'inspired', null, null, null, false, null, true),
  ('bg-sinai', 'Fundo do Monte Sinai', 'background', 'background', 'rare', 'Fundo ilustrado do monte Sinai (Êxodo 19:20). Recompensa da Coleção de Moisés.', 'Êxodo 19:20', 'background/bg-sinai', false, false, 7, null, null, 'collection', 'complementar', null, 'inspired', null, null, null, false, null, true),
  ('bg-bethlehem', 'Fundo dos Campos de Belém', 'background', 'background', 'rare', 'Os campos onde Davi apascentava as ovelhas (1 Samuel 16:11). Recompensa da Coleção de Davi.', '1 Samuel 16:11', 'background/bg-bethlehem', false, false, 7, null, null, 'collection', 'complementar', null, 'inspired', null, null, null, false, null, true)
