insert into public.reward_triggers (id, kind, name, description, book_code, chapter, is_active) values
  ('missao_manto_do_profeta', 'mission', 'Missão especial: o chamado de Eliseu', 'Leia 1 Reis 19 no Modo Missão: Elias lança o manto sobre Eliseu (1 Reis 19:19).', '1KI', 19, true),
  ('missao_vestes_do_sumo_sacerdote', 'mission', 'Missão especial: as vestes do sumo sacerdote', 'Leia Êxodo 28 no Modo Missão: a estola, o peitoral das doze pedras e o turbante de Arão (Êxodo 28:6-8, 15-21, 39-40).', 'EXO', 28, true),
  ('missao_arca_sobe_a_jerusalem', 'mission', 'Missão especial: a arca sobe a Jerusalém', 'Leia 1 Crônicas 15 no Modo Missão: Davi e os levitas, vestidos de linho, levam a arca (1 Crônicas 15:27).', '1CH', 15, true),
  ('missao_voz_no_deserto', 'mission', 'Missão especial: a voz que clama no deserto', 'Leia Mateus 3 no Modo Missão: João Batista, com roupa de pelos de camelo e cinto de couro (Mateus 3:4).', 'MAT', 3, true),
  ('missao_uncao_de_salomao', 'mission', 'Missão especial: a unção de Salomão', 'Leia 1 Reis 1 no Modo Missão: o povo celebra com flautas a unção de Salomão (1 Reis 1:40).', '1KI', 1, true),
  ('missao_o_atalaia', 'mission', 'Missão especial: o atalaia', 'Leia Ezequiel 33 no Modo Missão: o atalaia toca a trombeta para avisar o povo (Ezequiel 33:3-6).', 'EZK', 33, true),
  ('missao_esdras_o_escriba', 'mission', 'Missão especial: Esdras, o escriba', 'Leia Esdras 7 no Modo Missão: Esdras, escriba versado na Lei de Moisés (Esdras 7:6).', 'EZR', 7, true),
  ('missao_noiva_para_isaque', 'mission', 'Missão especial: uma noiva para Isaque', 'Leia Gênesis 24 no Modo Missão: o servo de Abraão presenteia Rebeca com braceletes (Gênesis 24:22).', 'GEN', 24, true),
  ('missao_jose_diante_de_farao', 'mission', 'Missão especial: José diante de Faraó', 'Leia Gênesis 41 no Modo Missão: Faraó entrega seu anel de selo a José (Gênesis 41:42).', 'GEN', 41, true),
  ('missao_ovelha_perdida', 'mission', 'Missão especial: a ovelha perdida', 'Leia Lucas 15 no Modo Missão. Item inspirado na parábola da ovelha perdida (Lucas 15:4-6).', 'LUK', 15, true),
  ('missao_tudo_que_tem_folego', 'mission', 'Missão especial: tudo o que tem fôlego', 'Leia Salmos 150 no Modo Missão: louvem com harpa e lira (Salmos 150:3-4).', 'PSA', 150, true),
  ('missao_consagracao_de_arao', 'mission', 'Missão especial: a consagração de Arão', 'Leia Levítico 8 no Modo Missão: Moisés veste Arão com a túnica (Levítico 8:7).', 'LEV', 8, true),
  ('missao_pes_do_mensageiro', 'mission', 'Missão especial: os pés do mensageiro', 'Leia Isaías 52 no Modo Missão. Item inspirado em “como são belos os pés dos que anunciam boas-novas” (Isaías 52:7), uma associação metafórica.', 'ISA', 52, true),
  ('missao_armadura_de_deus', 'mission', 'Missão especial: a armadura de Deus', 'Leia Efésios 6 no Modo Missão. Item inspirado no “cinto da verdade” da armadura de Deus (Efésios 6:14), uma associação simbólica.', 'EPH', 6, true)
