-- ARQUIVO GERADO por scripts/generate-catalog-sql.mjs — não edite à mão.
-- Catálogo de avatar v7: opções de aparência e itens iniciais gratuitos.

on conflict (id) do update set
  category = excluded.category, name = excluded.name,
  sort_order = excluded.sort_order, catalog_version = excluded.catalog_version, is_active = true;

-- Raridades (fonte: catalog.json).
on conflict (id) do update set name = excluded.name, sort_order = excluded.sort_order,
  color = excluded.color, description = excluded.description, is_active = true;

