on conflict (id) do update set
  name = excluded.name, category = excluded.category, slot = excluded.slot,
  rarity = excluded.rarity, description = excluded.description, scripture_ref = excluded.scripture_ref,
  asset_manifest_key = excluded.asset_manifest_key, is_starter = excluded.is_starter,
  is_premium_cosmetic = excluded.is_premium_cosmetic, catalog_version = excluded.catalog_version,
  body_compatibility = excluded.body_compatibility, variant_label = excluded.variant_label,
  acquisition = excluded.acquisition, series = excluded.series, book_code = excluded.book_code,
  representation = excluded.representation, meaning = excluded.meaning, referent = excluded.referent,
  holy_subtype = excluded.holy_subtype, shop_eligible = excluded.shop_eligible, shop_price_suggested = excluded.shop_price_suggested, is_active = true;

-- Aliases de compatibilidade (ID oficial ou do rascunho → ID canônico).
on conflict (alias_id) do update set item_id = excluded.item_id, source = excluded.source;

-- Missões curadas do Modo Missão (concluídas ao finalizar a missão de leitura do capítulo).
on conflict (id) do update set kind = excluded.kind, name = excluded.name, description = excluded.description,
  book_code = excluded.book_code, chapter = excluded.chapter, is_active = true;

-- Variantes evolutivas (cada variante é um item próprio; a base permanece).
update public.cosmetic_items set variant_of = 'cloak-elijah' where id = 'cloak-succession';
update public.cosmetic_items set variant_of = 'cloak-elijah' where id = 'cloak-elijah-prophets';

-- Regras de desbloqueio: itens iniciais são gratuitos e concedidos pelo servidor.
select i.id, 'starter', jsonb_build_object('catalogVersion', 7), 1
from public.cosmetic_items i
where i.is_starter and not i.is_premium_cosmetic
on conflict (item_id) where rule_type = 'starter' do nothing;

-- Regras anteriores dos itens do catálogo ficam inativas (histórico mantido); as atuais são reativadas abaixo.
